\begin{hbtheorem}{thm:p06-zorn}{cited=Jech1973Choice}{Choice equivalents and Zorn's lemma}
Over \(\mathsf{ZF}\), the following principles are equivalent.
\begin{enumerate}
  \item The Axiom of Choice as stated in
        Section~\ref{sec:set-prerequisites-06}.
  \item Every set can be well-ordered.
  \item \emph{Zorn's lemma}: if every chain in a poset \(P\), including the
        empty chain, has an upper bound in \(P\), then \(P\) has a maximal
        element.
  \item \emph{Hausdorff's maximal principle}: every chain in a poset is
        contained in a maximal chain.
  \item \emph{Tukey's lemma}: every family of finite character has a maximal
        member under inclusion.
  \item The Cartesian product of every set-indexed family of nonempty sets is
        nonempty.
  \item Tychonoff's theorem for arbitrary compact topological spaces.
\end{enumerate}
The compact-Hausdorff restriction of Tychonoff's theorem is deliberately not
on this list: over \(\mathsf{ZF}\) it is equivalent to the Boolean Prime Ideal
Theorem, hence to the Ultrafilter Lemma, and is strictly weaker than Choice in
the relative-consistency sense recorded in
Definition~\ref{def:ultrafilter-lemma}.
\index{Zorn's lemma}
\index{Hausdorff maximal principle}
\index{Tukey's lemma}
\index{Tychonoff theorem}
\index{Boolean Prime Ideal Theorem}
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-cardinal-trichotomy}{cited=Jech1973Choice}{Cardinal trichotomy and Choice}
Over \(\mathsf{ZF}\), the following are equivalent: the Axiom of Choice; and,
for every two sets \(A,B\), exactly one of these alternatives holds:
\(A\) has strictly smaller size than \(B\), \(A\approx B\), or \(B\) has
strictly smaller size than \(A\), with comparison understood as in
Definition~\ref{def:p06-size-comparison}.  This is a theorem about
arbitrary sets.  The trichotomy theorem for ordinals requires no Choice.
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-konig-infinity}{proved=annex:p6.choice.2}{K\"onig's infinity lemma for the binary tree}
In \(\mathsf{ZF}\), if a binary tree \(\mathcal T\subseteq2^{<\omega}\) has a
node at every level, then \(\mathcal T\) has an infinite branch.  No choice
principle is used.
\end{hbtheorem}

\begin{hbcorollary}{thm:p06-classical-fan}{proved=annex:p6.choice.3}{Classical fan theorem}
In \(\mathsf{ZF}\), if \(B\subseteq2^{<\omega}\) is a bar, then there is an
\(N\in\N\) such that every \(\mathbf s\in2^N\) has an initial segment in \(B\).
This is the classical contrapositive form supplied by K\"onig's infinity
lemma, not a claim about constructive fan principles.
\end{hbcorollary}

\begin{systementry}{entry:p08-ctl}{Computation tree logic CTL}
  \index{computation tree logic!CTL}
  \entrylanguage{Boolean state formulas with path quantifiers immediately
    paired with next or strong until, as in
    Definition~\ref{def:p08-ctl-semantics}.}
  \entrysemantics{States of total transition structures; path quantifiers range
    over infinite paths beginning at the current state.}
  \entrycalculus{sheet:hilbert-ctl}
  \entryadequacy{cited=EmersonHalpern1985}{The registered theoremhood calculus is
    sound and weakly complete for CTL validity on total transition structures.}
  \entrydecidability{cited=EmersonHalpern1985}{Satisfiability is
    EXPTIME-complete; combined finite-state model checking is P-complete and
    admits the standard linear-time-in-structure-times-formula algorithm
    \cite{ClarkeEmersonSistla1986}.}
  \entrycharacteristic{Can distinguish existential from universal branching,
    as Figure~\ref{fig:p08-ctl-tree} illustrates, but cannot retain an arbitrary
    LTL path formula beneath one path quantifier.}
  \entrytranslations{Embeds compositionally into CTL*.  Its fixed-point
    translation is recorded below only after the target language has been
    defined.}
  \entrysources{ClarkeEmerson1981,EmersonHalpern1985,ClarkeEmersonSistla1986}
\end{systementry}

\begin{systementry}{entry:p08-ctl-star}{Full computation tree logic CTL*}
  \index{computation tree logic!CTL*}
  \entrylanguage{The mutually generated state/path language of
    Definition~\ref{def:p08-ctl-star-semantics}.}
  \entrysemantics{State formulas are evaluated at states and path formulas on
    infinite paths of total transition structures.}
  \entrycalculus{sheet:hilbert-ctl-star}
  \entryadequacy{cited=Reynolds2001}{Reynolds's fullpath system, including its
    limit-closure schema and exact auxiliary-atoms side condition, is sound and
    weakly complete for standard CTL* validity.  Noncompactness precludes the
    corresponding arbitrary-premise strong-completeness claim.}
  \entrydecidability{cited=EmersonJutla1999}{Satisfiability is
    2EXPTIME-complete; combined finite-state model checking is PSPACE-complete
    \cite{EmersonLei1987}.}
  \entrycharacteristic{Strictly contains CTL and state-lifted LTL.  Its
    comparison with the later fixed-point language is stated only after that
    target language is defined.}
  \entrytranslations{The later fixed-point card records the exact target of
    the standard translation, generally with a nontrivial size increase.}
  \entrysources{EmersonHalpern1986,Reynolds2001,EmersonLei1987,EmersonJutla1999}
\end{systementry}

\begin{systementry}{entry:p08-modal-mu}{Propositional modal \(\mu\)-calculus}
  \index{modal mu-calculus@modal \(\mu\)-calculus}
  \entrylanguage{Kozen's primitive \(L_{\mu}\) language of
    Definition~\ref{def:p08-modal-mu-semantics}.}
  \entrysemantics{State extensions in Kozen models with one relation per
    program constant; least fixed points are taken in \(\mathcal P(S)\), and
    greatest fixed points are the displayed duals.}
  \entrycalculus{sheet:hilbert-mu}
  \entryadequacy{cited=Walukiewicz2000}{Kozen's equational axiomatization is
    sound and weakly complete for validity.  The exact theorem, equation
    form, finite-premise consequence, and failure of compactness are in
    Section~\ref{sec:p09-kozen-full-completeness}.}
  \entrydecidability{cited=Kozen1983}{Satisfiability is EXPTIME-complete.
    Finite-state model checking is polynomial-time equivalent to solving parity
    games and has a quasipolynomial algorithm; a polynomial-time algorithm is
    not known \cite{CaludeJainKhoussainovLiStephan2017}.}
  \entrycharacteristic{Captures bisimulation-invariant modal fixed-point
    properties; its one-program fragment strictly extends CTL* on transition
    systems.}
  \entrytranslations{CTL, LTL under state lifting, and CTL* embed into the
    one-program fragment by using one program constant for the transition
    relation.}
  \entrysources{Kozen1983,Walukiewicz2000,EmersonJutla1999,CaludeJainKhoussainovLiStephan2017}
\end{systementry}

\begin{hbdefinition}{def:p07-heyting-arithmetic}{Heyting arithmetic}
\emph{Heyting arithmetic}, \(\mathsf{HA}\), has the arithmetic language,
nonlogical axioms, equality axioms, and the Peano-arithmetic induction scheme
fixed in Section~\ref{sec:arithmetic-coding-01}, but uses intuitionistic
first-order logic instead of classical first-order logic.  It is a formal
first-order theory, not a semantic notion of constructive truth.  This
distinction is used by the calibration row here and by every soundness and
derivability statement in Chapter~\ref{sec:p07-functional-interpretations}.
\index{Heyting arithmetic}
\index{HA|see{Heyting arithmetic}}
\end{hbdefinition}

\begin{hbtheorem}{thm:p08-k3-lp-facts}{proved=annex:p8.matrix.2}{K3--LP theorem sets and dual consequence}
In the fixed constant-free \(\neg,\land,\lor\)-language:
\begin{enumerate}
  \item \(\mathbf K_3\) has no tautologies;
  \item the LP tautologies are exactly the classical tautologies;
  \item for finite formula sets \(\Gamma,\Delta\), if
        \(\Gamma\entails_S\Delta\) means that every valuation designating all
        members of \(\Gamma\) designates at least one member of \(\Delta\),
        then
        \[
          \Gamma\entails_{\mathbf K_3}\Delta
          \quad\text{ iff }\quad
          \neg\Delta\entails_{\mathsf{LP}}\neg\Gamma,
        \]
        where negation acts memberwise on each finite set.
\end{enumerate}
The third clause is the registered K3--LP duality.  It is not an unqualified
single-conclusion equivalence \cite{Priest1979,OmoriWansing2017}.
\end{hbtheorem}

\begin{hbtheorem}{thm:p10-countable-atomless-uniqueness}{proved=annex:p10.atomless.2}{Uniqueness of the countable atomless Boolean algebra}
Any two nontrivial countable atomless Boolean algebras are isomorphic.
More generally, every isomorphism between finite subalgebras of two
such algebras extends to an isomorphism of the whole algebras.
\end{hbtheorem}

\begin{hbdefinition}{def:p12-lcf-architecture}{LCF architecture}
An \emph{LCF architecture} is the programming discipline in which values of an
abstract theorem type can be constructed only by a small set of trusted
primitive inference functions, while untrusted tactics compose those
functions.  The identifier \(\mathsf{LCF}\) is necessary to name that
constructor boundary, stands for an implementation architecture rather than a
logic, and is not synonymous with exporting a portable proof object.  The
distinction is used in Theorem~\ref{thm:p12-lcf-boundary} and
Table~\ref{tab:p12-assistant-landscape}
\cite{GordonMilnerWadsworth1979}.
\index{LCF architecture}
\end{hbdefinition}

\begin{hbtheorem}{thm:p02-decidability}{cited=EbbinghausFlumThomas1994}{Decidability of classical propositional logic}
There is a terminating algorithm which, on finite encoded inputs, decides
whether a propositional formula is satisfiable or valid, whether two formulas
are logically equivalent, and whether a finite set \(\Gamma\) semantically
entails a formula \(\varphi\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p02-sat-np-complete}{cited=AroraBarak2009}{SAT NP-completeness}
\(\mathsf{SAT}\) is \(\mathsf{NP}\)-complete under polynomial-time many-one
reductions.
\end{hbtheorem}

\begin{hblemma}{thm:p02-interpolant-truth-table-correctness}{proved=annex:p2.3.9}{Correctness of the truth-table interpolant construction}
If \(\varphi\entails\psi\), the output of
Method~\ref{def:p02-interpolant-truth-table} is a Craig interpolant for that
consequence.
\end{hblemma}

\begin{hbtheorem}{thm:p02-horn-sat}{cited=DowlingGallier1984}{Horn-SAT tractability}
Horn satisfiability is decidable in time linear in the input size by forward
chaining (equivalently, unit propagation in the implicational presentation):
after the empty-clause check, the bound is \(O(N)\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p02-herbrand-validity}{cited=AfshariEnqvistLeigh2025}{Herbrand's theorem, validity form}
Let \(\Lang\) be equality-free and contain a ground term, and let
\(\sigma=\exists\bar x\,\varphi(\bar x)\) be a prenex existential \(\Lang\)-sentence
with quantifier-free matrix.  Then \(\sigma\) is first-order valid iff some
finite Herbrand expansion of \(\sigma\) is propositionally valid.  If the
original signature has no ground term, the same equivalence holds after adding
one fresh constant as above.
\index{Herbrand's theorem!validity form}
\end{hbtheorem}

\begin{hbtheorem}{thm:p02-beth-definability}{cited=Beth1953}{Beth definability theorem}
For every first-order theory \(T(P)\) as in
Definition~\ref{def:p02-beth-definability}, \(T(P)\) implicitly defines \(P\)
over \(\Lang\) iff it explicitly defines \(P\) over \(\Lang\).
\index{Beth definability theorem}
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-craig-robinson-beth}{proved=annex:p3.abstract.5}{Craig--Robinson equivalence and Beth definability}
For classical first-order logic, using compactness, Craig interpolation
and the common-sentence form of Robinson joint consistency imply one
another.  Each implies Beth definability.
\end{hbtheorem}

\begin{theorem}[Conservativity of definitional extensions]
\label{thm:definitional-conservativity}
Let \(T\), \(R\), \(\varphi\), and \(\delta_R\) be as in the preceding
example, and let \(\Lang_R\) denote the signature extending \(\Lang\) by
the single relation symbol \(R\).
\begin{enumerate}
  \item Every \(\Lang\)-model \(\Meta\) of \(T\) has exactly one
        \(\Lang_R\)-expansion satisfying \(\delta_R\), and that expansion
        is a model of \(T\cup\set{\delta_R}\).
  \item The extension is \emph{conservative}: for every
        \(\sigma\in\Sent(\Lang)\),
        \(T\cup\set{\delta_R}\entails\sigma\) iff
        \(T\entails\sigma\).
\end{enumerate}
\textit{Status: complete proof.}
\end{theorem}

\begin{hbtheorem}{thm:p03-ef}{cited=Ehrenfeucht1961}{Ehrenfeucht--Fra\"iss\'e theorem}
For structures \(\mathcal A\) and \(\mathcal B\) in the same fixed finite
relational signature, Duplicator has a winning strategy in the \(k\)-round
Ehrenfeucht--Fra\"iss\'e game if and only if \(\mathcal A\) and
\(\mathcal B\) agree through rank \(k\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-los-tarski}{cited=ChangKeisler1990}{Los--Tarski preservation theorem@\L o\'s--Tarski preservation theorem}
For an elementary class \(\mathcal K\) of \(\Lang\)-structures, the following
are equivalent:
\begin{enumerate}
 \item \(\mathcal K\) is closed under substructures;
 \item \(\mathcal K\) is axiomatizable by universal \(\Lang\)-sentences.
\end{enumerate}
Equivalently at sentence level, a first-order sentence is preserved under
extensions iff it is logically equivalent, over all \(\Lang\)-structures, to
an existential sentence.
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-chang-los-suszko}{cited=ChangKeisler1990}{Chang--Los--Suszko theorem@Chang--\L o\'s--Suszko theorem}
For an elementary class \(\mathcal K\) of \(\Lang\)-structures, the following
are equivalent:
\begin{enumerate}
 \item \(\mathcal K\) is closed under unions of chains of substructures;
 \item \(\mathcal K\) is axiomatizable by sentences of the form
       \(\forall\bar x\,\exists\bar y\,\theta(\bar x,\bar y)\), where
       \(\theta\) is quantifier-free and either quantifier block may be empty.
\end{enumerate}
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-lyndon-preservation}{cited=Lyndon1959}{Lyndon positivity theorem}
In a relational signature with equality, a first-order formula is preserved
under surjective homomorphisms between all structures iff it is logically
equivalent to a positive formula.
\end{hbtheorem}

\begin{proofboundary}{def:p03-ultrafilter-choice-boundary}{Boolean prime ideals, ultrafilters, and Choice}
Over \(\mathsf{ZF}\), the Boolean Prime Ideal Theorem is equivalent to the
Ultrafilter Lemma and is strictly weaker than the full Axiom of Choice, relative
to the usual consistency assumptions \cite{HowardRubin1998}.  Applied to the
cofinite filter on \(\mathbb N\), it suffices for the existence of a
nonprincipal ultrafilter.

The exact inherited development is written under the handbook's ambient
\(\mathsf{AC}\) convention.  Its assumption map is:
\begin{itemize}
  \item extending the cofinite filter to a nonprincipal ultrafilter needs only
        the Ultrafilter Lemma;
  \item the inherited type-space compactness proof invokes the already stated
        first-order compactness theorem in its ambient metatheory rather than
        claiming a new \(\mathsf{ZF}+\mathsf{BPI}\) calibration;
  \item the existential step in Los's theorem selects witnesses across the
        relevant index set, so the displayed proof retains full Choice;
  \item compactness via ultraproducts uses an ultrafilter on finite subtheories
        and also selects one model for each finite subtheory, so the displayed
        proof likewise retains full Choice; and
  \item the Keisler--Shelah theorem remains cited under the ambient Choice
        convention and is not weakened here.
\end{itemize}
The distinctions are metatheoretic assumption boundaries, not new axioms of
the object theories.
\index{Boolean Prime Ideal Theorem}\index{Ultrafilter Lemma}\index{Axiom of Choice}
\end{proofboundary}

\begin{hbtheorem}{thm:p03-prime-atomic}{cited=Marker2002}{Prime--atomic model package}
Let \(T\) be a complete satisfiable theory in a countable language.
\begin{enumerate}
  \item For every \emph{countable} \(\mathcal M\entails T\), the model
        \(\mathcal M\) is prime if and only if it is atomic.
  \item The theory \(T\) has a prime model if and only if, for every
        \(n<\omega\), the isolated types are dense in \(S_n(T)\).
\end{enumerate}
The countability restriction belongs to clause~1: an arbitrary atomic model
need not be prime.
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-countable-saturated}{cited=Marker2002}{Countable saturated-model package}
Let \(T\) be a complete theory in a countable language with an infinite
model.
\begin{enumerate}
  \item The theory \(T\) has a countable saturated model if and only if it is
        small.
  \item Any two countable saturated models of \(T\) are isomorphic.
\end{enumerate}
Here ``saturated'' uses the handbook convention: a countable model realizes
every complete finite-tuple type over every finite parameter set.
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-ehrenfeucht-mostowski}{cited=EhrenfeuchtMostowski1956}{Ehrenfeucht--Mostowski indiscernibles}
Let \(T\) be a first-order theory with an infinite model, and let \((I,<)\)
be any linear order.  Some model of \(T\) contains a sequence of distinct
order indiscernibles indexed in order type \(I\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-em-models}{cited=EhrenfeuchtMostowski1956}{Ehrenfeucht--Mostowski models}
For every first-order theory \(T\) with an infinite model there is a blueprint
\(\Phi\) such that \(\operatorname{EM}(I,\Phi)\entails T\) for every linear
order \(I\), and every order embedding \(I\to J\) induces an elementary
embedding of the corresponding \(\Lang\)-reducts.
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-ominimal-monotonicity}{cited=PillaySteinhorn1986}{O-minimal monotonicity theorem}
Let \(f:(a,b)\to M\) be definable in an o-minimal structure, with parameters
allowed.  There is a finite partition of \((a,b)\) into points and open
intervals such that on each interval \(f\) is continuous and is either
constant, strictly increasing, or strictly decreasing.
\end{hbtheorem}

\begin{hbtheorem}{thm:p03-fagin}{cited=Fagin1974}{Fagin's theorem}
Over finite relational structures, an isomorphism-closed property belongs to
\(\mathsf{NP}\) if and only if it is definable by an existential second-order
sentence.
\end{hbtheorem}

\begin{hbdefinition}{def:p03-computable-presentation}{Computable presentations}
For a countable structure \(A\), a presentation with domain \(\mathbb N\) is
\emph{computable} when its atomic diagram is decidable.  A computable copy is
an isomorphic structure with such a presentation.  This name is needed because
the existence of an abstract countable copy says nothing about whether its
atomic facts can be decided.  It is a property of a concrete presentation,
not finite-model decidability or a property of every isomorphic copy.  The
distinction is used in the computable-categoricity definition below.
\index{computable presentation}
\index{computable model theory}
\end{hbdefinition}

\begin{hbtheorem}{thm:p03-lindstrom}{proved=annex:p3.abstract.3}{Lindstrom's theorem@Lindstr\"om's theorem}
Let \(\mathcal L^{\ast}\) be a regular abstract logic in that fixed relational
sense.  Assume:
\begin{enumerate}
 \item whenever a countable set of \(\mathcal L^{\ast}\)-sentences has every
       finite subset satisfiable, the whole set is satisfiable; and
 \item every satisfiable \(\mathcal L^{\ast}\)-sentence has a countable model.
\end{enumerate}
Then every \(\mathcal L^{\ast}\)-sentence is equivalent, over its finite
occurrence signature, to a relational first-order sentence.  Conversely,
first-order sentences already belong to \(\mathcal L^{\ast}\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p04-tm-partial-recursive}{cited=Kleene1952}{Turing-computable iff partial recursive}
For every \(k\ge1\) and every partial map
\(f:\N^k\rightharpoonup\N\), the following are equivalent:
\begin{enumerate}
  \item \(f\) is computed by a Turing machine under
        the named Turing-machine definition in
        Section~\ref{sec:turing-machines-01} and
        Definition~\ref{def:partial-computable};
  \item \(f\) is partial recursive in the closure sense of
        Definition~\ref{def:p04-partial-recursive}.
\end{enumerate}
\end{hbtheorem}

\begin{hbtheorem}{thm:p04-kleene-post}{proved=annex:p4.degrees.2}{Kleene--Post incomparability theorem}
There are Turing degrees \(\mathbf a,\mathbf b<\mathbf0'\) such that neither
\(\mathbf a\leq\mathbf b\) nor \(\mathbf b\leq\mathbf a\).  No claim that
these two degrees are c.e. is made by this theorem.
\end{hbtheorem}

\begin{hbtheorem}{thm:p04-friedberg-muchnik}{proved=annex:p4.degrees.4}{Friedberg--Muchnik theorem}
There are computably enumerable sets \(A,B\subseteq\N\) such that
\(A\not\leq_TB\) and \(B\not\leq_TA\).  Consequently there are incomparable
c.e. degrees strictly between \(\mathbf0\) and \(\mathbf0'\), answering
Post's problem.
\end{hbtheorem}

\begin{hbtheorem}{thm:p05-presburger-qe}{cited=Presburger1929}{Quantifier elimination and decidability}
After adding all congruence predicates, every Presburger formula is equivalent
over \(\mathbb N\) to a quantifier-free formula. Consequently Presburger
arithmetic is complete and decidable.
\end{hbtheorem}

\begin{hbtheorem}{thm:p05-goodstein-termination}{cited=Goodstein1944}{Goodstein termination}
For every \(m\in\N\), some \(s\) satisfies \(g^m_s=0\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p05-modal-fixed-point}{cited=Sambin1976}{Modal fixed-point theorem}
If every occurrence of \(p\) in \(A(p)\) is within the scope of a box, then
there is a formula \(F\) not containing \(p\) such that
\(\mathsf{GL}\vdash F\leftrightarrow A(F)\).  The modalized-occurrence
hypothesis cannot be deleted.
\end{hbtheorem}

\begin{hbdefinition}{def:p06-diamond}{The diamond principle at omega-one}
The principle \(\diamondsuit_{\omega_1}\) asserts that there is a sequence
\(\langle A_\alpha:\alpha<\omega_1\rangle\) such that
\(A_\alpha\subseteq\alpha\) and, for every \(A\subseteq\omega_1\),
\[
  \{\alpha<\omega_1:A\cap\alpha=A_\alpha\}
\]
is stationary in \(\omega_1\).  The suit-shaped \(\diamondsuit\) denotes a
set-theoretic guessing principle, not the modal possibility operator.
\index{diamond principle@\(\diamondsuit\) principle}
\end{hbdefinition}

\begin{hbtheorem}{thm:p06-square-aronszajn}{cited=Jensen1972FineStructure}{Square produces an Aronszajn tree}
For every infinite cardinal \(\kappa\), the full principle
\(\square_\kappa\) implies that a \(\kappa^+\)-Aronszajn tree exists.  This
is an application of the no-thread clause, not merely of coherence
\cite{Jensen1972FineStructure}.
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-ma-suslin}{cited=MartinSolovay1970}{Martin's axiom and Suslin trees}
The axiom \(\mathsf{MA}_{\aleph_1}\) implies the Suslin hypothesis.  Hence
\(\mathsf{MA}+\neg\mathsf{CH}\) implies \(\mathsf{SH}\), since then
\(\aleph_1<\mathfrak c\) \cite{MartinSolovay1970,Jech2003}.
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-scott-measurable}{cited=Scott1961}{Scott's constructibility obstruction}
If a measurable cardinal exists, then \(V\ne L\).  The theorem does not say
that every large-cardinal property is incompatible with constructibility.
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-fodor}{cited=Fodor1956}{Fodor's pressing-down lemma}
Let \(S\subseteq\kappa\) be stationary and let \(f:S\to\kappa\) be
\emph{regressive}: \(f(\alpha)<\alpha\) for every nonzero
\(\alpha\in S\).  Then for some \(\beta<\kappa\), the fiber
\[
  \{\alpha\in S:f(\alpha)=\beta\}
\]
is stationary.  The conclusion is stationary, not merely uncountable
\cite{Fodor1956}.
\index{Fodor's lemma}\index{pressing-down lemma}
\end{hbtheorem}

\begin{hblemma}{thm:p06-add-ccc}{proved=annex:p6.comb.2}{The Cohen poset is ccc}
For every infinite cardinal \(\kappa\),
\(\operatorname{Add}(\omega,\kappa)\) has the countable chain condition.
\end{hblemma}

\begin{hbtheorem}{thm:p06-ccc-preservation}{proved=annex:p6.force.9}{Cardinal and cofinality preservation by ccc forcing}
Assume \((M,\in)\entails\mathsf{ZFC}\), \(M\) regards \(\mathbb P\) as ccc,
and \(G\) is \(M\)-generic.  Then every \(M\)-cardinal remains a cardinal of
\(M[G]\), and every ordinal has the same cofinality as computed in \(M\) and
\(M[G]\).
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-gale-stewart}{cited=GaleStewart1953}{Open and closed determinacy}
\(\mathsf{ZF}\) proves that if \(A\subseteq\omega^\omega\) is open or
closed, then \(G(A)\) is determined.  No choice principle is required.
\end{hbtheorem}

\begin{hbtheorem}{thm:p06-borel-determinacy}{cited=Martin1975}{Borel determinacy}
Every game \(G(A)\) with Borel payoff
\(A\subseteq\omega^\omega\) is determined in \(\mathsf{ZFC}\).  This is a
statement of Martin's theorem, not a local compression of its proof.
\index{Borel determinacy}
\end{hbtheorem}

\begin{hbtheorem}{thm:p07-system-f-strong-normalization}{cited=Girard1972}{Strong normalization for System F}
Every term typable on Sheet~\ref{sheet:system-f} admits no infinite sequence
of term-beta and type-beta contractions.
\end{hbtheorem}
